// One-time migration to Evan's reviewed navigation; subsequent edits remain device-local.
(()=>{try{const key='ranch-navigation-policy-v2';if(localStorage.getItem(key)!=='2026-10-19-slim'){localStorage.setItem('ranch-navigation-order-v1',JSON.stringify(['/sandbox','/procedural','/units','/proportion-study','/themes','/mood-board','/tools']));localStorage.setItem('ranch-navigation-hidden-v1',JSON.stringify(['/units','/themes','/mood-board']));localStorage.setItem(key,'2026-10-19-slim');}}catch{}})();
(()=>{const mobile=()=>matchMedia('(max-width:799px)').matches,header=document.querySelector('header'),nav=document.createElement('aside');nav.id='left-navigation';nav.setAttribute('aria-label','Ranch navigation');nav.innerHTML='<div class="nav-title">ABBIE’S RANCH<button id="nav-close" aria-label="Close navigation">×</button></div><a class="nav-link" href="/procedural">Terrain Generator</a><a class="nav-link" href="/sandbox">Sandbox</a><a class="nav-link" href="/units">Units</a><a class="nav-link" href="/proportion-study">Proportion Study</a><a class="nav-link" href="/themes">Themes</a><a class="nav-link" href="/mood-board">Mood Board</a><a class="nav-link" href="/tools">Tools / Utilities</a>';

const orderKey='ranch-navigation-order-v1',links=[...nav.querySelectorAll('.nav-link')],list=document.createElement('div');list.className='nav-items';nav.querySelector('.nav-title').after(list);
let saved=['/sandbox','/procedural','/units','/proportion-study','/themes','/mood-board','/tools'];try{const value=JSON.parse(localStorage.getItem(orderKey));if(Array.isArray(value))saved=value;}catch{}
links.sort((a,b)=>{const rank=x=>{const i=saved.indexOf(x.getAttribute('href'));return i<0?saved.length:i;};return rank(a)-rank(b);});
const notice=document.createElement('span');notice.className='nav-order-status';notice.setAttribute('role','status');list.after(notice);
const hiddenKey='ranch-navigation-hidden-v1';let hiddenItems=['/units','/themes','/mood-board'];try{const value=JSON.parse(localStorage.getItem(hiddenKey));if(Array.isArray(value))hiddenItems=value;}catch{}

let editing=false;
const settings=document.createElement('button');settings.id='nav-settings';settings.textContent='Settings';settings.setAttribute('aria-expanded','false');settings.setAttribute('aria-controls','ranch-nav-items');list.id='ranch-nav-items';nav.append(settings);
const drawer=document.createElement('dialog');drawer.id='navigation-settings-drawer';drawer.className='nav-editing';drawer.setAttribute('aria-labelledby','navigation-settings-title');drawer.innerHTML='<div class="navigation-settings-heading"><h2 id="navigation-settings-title">Navigation</h2><button id="settings-close" aria-label="Close settings">×</button></div>';document.body.append(drawer);const visibleList=document.createElement('div');visibleList.className='nav-items';list.before(visibleList);drawer.append(list,notice);let restoreNav=false;
function syncNavigation(){visibleList.replaceChildren(...[...list.querySelectorAll('a')].filter(a=>!hiddenItems.includes(a.getAttribute('href'))).map(a=>a.cloneNode(true)));}
function closeSettings(){drawer.close();}
drawer.querySelector('#settings-close').onclick=closeSettings;drawer.addEventListener('click',e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSettings();}});drawer.addEventListener('close',()=>{editing=false;renderSettings();if(restoreNav){openNav();settings.focus();}else settings.focus();});
function renderSettings(){settings.textContent='Settings';settings.setAttribute('aria-expanded',String(editing));for(const row of list.children){const href=row.querySelector('a').getAttribute('href'),isHidden=hiddenItems.includes(href);row.hidden=isHidden&&!editing;row.classList.toggle('nav-item-hidden',isHidden);const control=row.querySelector('.nav-visibility');control.textContent=isHidden?'Add':'Hide';control.setAttribute('aria-label',(isHidden?'Add ':'Hide ')+row.querySelector('a').textContent);row.querySelector('.nav-drag-handle').hidden=!editing;control.hidden=!editing;}syncNavigation();}
settings.onclick=()=>{restoreNav=mobile()&&nav.classList.contains('nav-open');if(restoreNav)closeNav(false);editing=true;renderSettings();drawer.showModal();drawer.querySelector('#settings-close').focus();};
function saveOrder(){syncNavigation();try{localStorage.setItem(orderKey,JSON.stringify([...list.querySelectorAll('a')].map(a=>a.getAttribute('href'))));notice.textContent='Order saved';}catch{notice.textContent='Order changed. Device saving unavailable.';}}
for(const link of links){const row=document.createElement('div');row.className='nav-item';row.append(link);link.onclick=e=>e.preventDefault();const handle=document.createElement('button');handle.className='nav-drag-handle';handle.textContent='⠿';handle.setAttribute('aria-label','Reorder '+link.textContent);handle.title='Drag to reorder. Use arrow keys when focused.';row.append(handle);const visibility=document.createElement('button');visibility.className='nav-visibility';visibility.onclick=()=>{const href=link.getAttribute('href');hiddenItems=hiddenItems.includes(href)?hiddenItems.filter(x=>x!==href):[...hiddenItems,href];try{localStorage.setItem(hiddenKey,JSON.stringify(hiddenItems));notice.textContent='Navigation saved';}catch{notice.textContent='Device saving unavailable';}renderSettings();};row.append(visibility);list.append(row);
let dragging=false,startOrder;
handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();handle.focus();startOrder=[...list.children];dragging=true;handle.setPointerCapture(e.pointerId);row.classList.add('dragging');});
handle.addEventListener('pointermove',e=>{if(!dragging)return;const others=[...list.children].filter(item=>item!==row);const next=others.find(item=>e.clientY<item.getBoundingClientRect().top+item.getBoundingClientRect().height/2);list.insertBefore(row,next||null);handle.setPointerCapture(e.pointerId);});
function finish(cancel=false){if(!dragging)return;dragging=false;row.classList.remove('dragging');if(cancel)startOrder.forEach(item=>list.append(item));else saveOrder();}
handle.addEventListener('pointerup',()=>finish());handle.addEventListener('pointercancel',()=>finish(true));
handle.addEventListener('keydown',e=>{if(e.key==='Escape'&&dragging){e.preventDefault();e.stopPropagation();finish(true);return;}if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const prev=row.previousElementSibling,next=row.nextElementSibling;if(e.key==='ArrowUp'&&prev)list.insertBefore(row,prev);if(e.key==='ArrowDown'&&next)list.insertBefore(next,row);if(e.key==='Home')list.prepend(row);if(e.key==='End')list.append(row);handle.focus();saveOrder();});}
renderSettings();
const dock=document.querySelector('.dock');if(dock)dock.hidden=true;
document.body.append(nav);const scrim=document.createElement('button');scrim.id='nav-shade';scrim.hidden=true;scrim.setAttribute('aria-label','Close navigation');document.body.append(scrim);const toggle=document.createElement('button');toggle.id='nav-toggle';toggle.setAttribute('aria-label','Open navigation');toggle.setAttribute('aria-controls','left-navigation');toggle.setAttribute('aria-expanded','false');toggle.textContent='☰';header.prepend(toggle);const brand=header.querySelector('.brand');if(brand){brand.querySelectorAll('.seal,.ranch-brand-logo').forEach(mark=>mark.remove());const title=brand.querySelector('strong');if(title&&/ranch/i.test(title.textContent))title.textContent='Abbie’s Ranch';}const about=document.getElementById('about');if(about)about.textContent='?';
let prior;function closeNav(focus=true){nav.classList.remove('nav-open');scrim.hidden=true;toggle.setAttribute('aria-expanded','false');nav.removeAttribute('role');nav.removeAttribute('aria-modal');document.querySelector('main').inert=false;header.inert=false;nav.inert=mobile()||document.body.classList.contains('board3');if(focus&&prior)prior.focus();}
function openNav(){prior=document.activeElement;nav.inert=false;nav.classList.add('nav-open');nav.setAttribute('role','dialog');nav.setAttribute('aria-modal','true');scrim.hidden=false;toggle.setAttribute('aria-expanded','true');document.querySelector('main').inert=true;header.inert=true;document.getElementById('nav-close').focus();}
window.RanchNavigation={open:openNav,close:closeNav,settings:()=>settings.onclick(),read:()=>({order:[...list.querySelectorAll('a')].map(a=>a.getAttribute('href')),hidden:[...hiddenItems]})};window.RanchView?.register('navigation',()=>window.RanchNavigation.read());
toggle.onclick=openNav;document.getElementById('nav-close').onclick=()=>closeNav();scrim.onclick=()=>closeNav();nav.addEventListener('click',e=>{const selectedLink=e.target.closest('.nav-link');if(editing&&selectedLink){e.preventDefault();return;}if(!mobile())return;const link=e.target.closest('a');if(link){e.preventDefault();const href=link.href;closeNav(false);location.assign(href);}else if(e.target.closest('.ranch-nav-actions button'))closeNav(false);});document.addEventListener('keydown',e=>{if(!nav.classList.contains('nav-open'))return;if(e.key==='Escape'){e.preventDefault();closeNav();}if(e.key==='Tab'){const items=[...nav.querySelectorAll('a,button')].filter(e=>!e.disabled&&e.getClientRects().length);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});window.addEventListener('resize',()=>{if(!mobile())closeNav(false);else if(!nav.classList.contains('nav-open'))nav.inert=true;});nav.inert=mobile();for(const a of nav.querySelectorAll('a'))if(new URL(a.href).pathname===location.pathname||(a.getAttribute('href')==='/procedural'&&location.pathname==='/procedural.html'))a.setAttribute('aria-current','page');})();


(()=>{if(document.body.classList.contains('board3'))return;const c=document.createElement('link');c.rel='stylesheet';c.href='/app-drawers.css?v=landscape-2';document.head.append(c);const s=document.createElement('script');s.src='/app-drawers.js?v=1';document.body.append(s);})();

(()=>{if(!document.querySelector('link[href^="/app-style.css"]')){const c=document.createElement("link");c.rel="stylesheet";c.href="/app-style.css?v=sunroom-1";document.head.append(c);}})();

// Keep scene discovery within reach of the generator controls on mobile too.